CREATE   VIEW [RegsBI].[vwIncident_CE]
AS
SELECT 
	[IncidentId],
	[AccountId],
	[CaseOriginCode],
	ISNULL([CaseOrigin_Description], 'Unknown') AS [CaseOrigin_Description],
	[ContactId],
	[CreatedBy],
	[CreatedByName],
	[Created_On],
	[ModifiedBy],
	[ModifiedByName],
	[Modified_On],
	[CustomerId],
	[OwnerId],
	[OwnerIdName],
	[PriorityCode],
	[PriorityCode_Description],
	[Rics_ProcessDescription],
	[StateCode],
	[StateCode_Description],
	[StatusCode],
	[StatusCode_Description],
	[SubjectId],
	[SubjectIdName],
	[Title],
	[rics_duedate],
	[overriddencreatedon],
	[ricsv1_regulatedschemeid],
	[OwningUser],
	[OwningTeam],
	[apuk_originatingdate],
	[apuk_statuschangeddate],
	[apuk_responseduein],
	[apuk_reasonforcontactsubcategory],
	[apuk_reasonforcontactsubcategory_descripiton],
	[apuk_reasonforcontact],
	[apuk_reasonforcontact_description],
	[onholdtime],
	[apuk_escalatedon],
	[apuk_escalatetoteamleader],
	[apuk_contactemailaddress],
	[apuk_category],
	[apuk_category_description]
FROM [CE].[vwIncident]
